import type {
  ICartModuleService,
  IOrderModuleService,
  MedusaContainer,
} from "@medusajs/framework/types"
import { ContainerRegistrationKeys, Modules } from "@medusajs/framework/utils"

type Container = Pick<MedusaContainer, "resolve">

type Row = Record<string, unknown>

/** A line's metadata with the personal part gone; null when there was nothing to erase. */
export type LineMetadataRewrite = (metadata: unknown) => Row | null

interface MetadataRow {
  id: string
  metadata?: Row | null
}

// Generated by Medusa's service factory, not declared on the module's type (2.21)
interface OrderItemRecords {
  listOrderItems: (
    filters: { item_id: string[] },
    config: { select: string[]; take: null }
  ) => Promise<MetadataRow[]>
}

/**
 * The rows whose metadata the rewrite changes, each with its new metadata.
 * JSON columns merge on update: the rewrite returns the whole record, and
 * the key it changes is written over as a whole.
 */
export function rewrittenRows(
  rows: readonly MetadataRow[],
  rewrite: LineMetadataRewrite
): { id: string; metadata: Row }[] {
  return rows.flatMap((row) => {
    const metadata = rewrite(row.metadata)
    return metadata ? [{ id: row.id, metadata }] : []
  })
}

/**
 * Every stored copy of these orders' line metadata, rewritten (adr/0052
 * §10 Ek 2026-11-09): Medusa keeps one on the line item and one on the
 * order item of each order version (2.16+: an order read with its totals
 * shows the current version's), and the cart line it came from keeps its
 * own. Each copy is rewritten from itself, so a version that changed its
 * metadata keeps the rest of it. Run again, it changes nothing more.
 * Returns how many line items changed.
 */
export async function rewriteOrderLines(
  container: Container,
  orderIds: readonly string[],
  rewrite: LineMetadataRewrite
): Promise<number> {
  if (orderIds.length === 0) {
    return 0
  }
  const { data } = await container.resolve(ContainerRegistrationKeys.QUERY).graph({
    entity: "order",
    fields: ["id", "items.id", "cart.id"],
    filters: { id: [...orderIds] },
  })
  const rows = data as { items?: ({ id: string } | null)[] | null; cart?: { id?: string } | null }[]
  const itemIds = rows.flatMap((row) =>
    (row.items ?? []).flatMap((item) => (item ? [item.id] : []))
  )
  const orders = container.resolve<IOrderModuleService>(Modules.ORDER)
  let erased = 0
  if (itemIds.length > 0) {
    const lines = await orders.listOrderLineItems(
      { id: itemIds },
      { select: ["id", "metadata"], take: null }
    )
    for (const line of rewrittenRows(lines, rewrite)) {
      await orders.updateOrderLineItems(line.id, { metadata: line.metadata })
      erased += 1
    }
    // Every version's, not only the current one: an older version is read back too
    const versions = await (orders as unknown as OrderItemRecords).listOrderItems(
      { item_id: itemIds },
      { select: ["id", "metadata"], take: null }
    )
    const changed = rewrittenRows(versions, rewrite)
    if (changed.length > 0) {
      await orders.updateOrderItem(
        changed.map((row) => ({ selector: { id: row.id }, data: { metadata: row.metadata } }))
      )
    }
  }
  const cartIds = rows.flatMap((row) => (row.cart?.id ? [row.cart.id] : []))
  if (cartIds.length > 0) {
    const carts = container.resolve<ICartModuleService>(Modules.CART)
    const lines = await carts.listLineItems(
      { cart_id: cartIds },
      { select: ["id", "metadata"], take: null }
    )
    for (const line of rewrittenRows(lines, rewrite)) {
      await carts.updateLineItems(line.id, { metadata: line.metadata })
    }
  }
  return erased
}
